import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.CyZTVJbV.js";const h=JSON.parse('{"title":"kiwa v1.29 released — release script filter systematic root cause SSOT 化 (release-invariants v0.1 + hook + release-smoke axis + tutorial 55 + 7 milestone snippet streak)","description":"","frontmatter":{"title":"kiwa v1.29 released — release script filter systematic root cause SSOT 化 (release-invariants v0.1 + hook + release-smoke axis + tutorial 55 + 7 milestone snippet streak)","emoji":"🧷","type":"tech","topics":["oss","typescript","monorepo","release-gate","kiwa"],"published":true},"headers":[],"relativePath":"announcements/v1.29/zenn-article.md","filePath":"announcements/v1.29/zenn-article.md"}'),r={name:"announcements/v1.29/zenn-article.md"};function o(n,e,l,c,p,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="kiwa-v1-29-released" tabindex="-1">kiwa v1.29 released <a class="header-anchor" href="#kiwa-v1-29-released" aria-label="Permalink to &quot;kiwa v1.29 released&quot;">​</a></h1><p>v1.29 は kiwa の 19 milestone 目です。 v1.11-v1.28 の 18 milestone 連続完遂 retrospective で発見された <strong>release script filter systematic root cause pattern</strong> の 4 milestone 連続 event (v1.14 payment / v1.25 perf-harness / v1.27 quality-metrics / v1.28 realtime) を、 hook + release-smoke test axis + SSOT docs + 新規 npm package の 4 layer で自動化する最軽量 sprint。 kiwa quality gate SSOT の <strong>final hole</strong> (新 package 追加時の release script filter manual update 依存) を埋めた。 v1.11 以降の連続完遂 18 milestone (release gate → 非決定性 → 時間軸 → 横軸拡張 → AI-LLM 深化 → component 縦軸 → Observability v2 → Blockchain 深化 → Framework 深化 → Streaming 深化 → Auth 深化 → Auth 深化 II → Payment 深化 → Edge / Serverless 深化 → Perf-harness sweep → Database 深化 → Mutation testing sweep → Realtime 深化 II) を受けて、 v1.29 は release script filter systematic root cause SSOT 化 milestone、 kiwa runtime fixture 34 → <strong>35 packages</strong> (<code>@kiwa/release-invariants</code> v0.1.0 新規)。</p><h2 id="_4-回繰返された-bug-—-release-script-filter-対称性" tabindex="-1">4 回繰返された bug — release script filter 対称性 <a class="header-anchor" href="#_4-回繰返された-bug-—-release-script-filter-対称性" aria-label="Permalink to &quot;4 回繰返された bug — release script filter 対称性&quot;">​</a></h2><p><code>scripts.release</code> は 2 段構成の shell script。</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scripts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;release&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;pnpm -F @kiwa/core -F @kiwa/realtime build &amp;&amp; &quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;"> +</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;pnpm publish --filter @kiwa/core --filter @kiwa/realtime --access public --no-git-checks&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>前半 (<code>pnpm -F {name} build</code>) は build filter、 後半 (<code>pnpm publish --filter {name}</code>) は publish filter。 <code>-F</code> と <code>--filter</code> は syntactic に別 flag、 意味的にも別段階を担当する。 新 package を追加する PR で contributor が <strong>片方だけ</strong> 追加した場合 —</p><ul><li>build filter だけ追加 → build は artefact を dist に出す、 publish 段階で package が渡されず npm に publish されない</li><li>publish filter だけ追加 → dist が古い、 publish は <code>pnpm publish</code> に「build されていない package を publish しろ」 と要求して失敗 or 古い dist を publish</li></ul><p>いずれも <strong>release script は exit 0</strong>、 milestone finisher の release-smoke test は特に fail-fast しない、 milestone 完了として merge される。 npm registry には新 package が届かない (or 古い dist が届く)。</p><p>v1.14 payment、 v1.25 perf-harness、 v1.27 quality-metrics、 v1.28 realtime の 4 milestone で <strong>全く同じ bug</strong> が独立に発生。 都度 follow-up PR で fix + release-smoke <code>v1-X-publish.test.ts</code> に「この milestone は package を filter に追加した」 assert が 1 行追加される。 次 milestone で同じ bug が再発。</p><h2 id="主な追加" tabindex="-1">主な追加 <a class="header-anchor" href="#主な追加" aria-label="Permalink to &quot;主な追加&quot;">​</a></h2><h3 id="kiwa-release-invariants-v0-1-0-3-pure-invariant-checker-1-shot-aggregator" tabindex="-1"><code>@kiwa/release-invariants</code> v0.1.0 (3 pure invariant checker + 1-shot aggregator) <a class="header-anchor" href="#kiwa-release-invariants-v0-1-0-3-pure-invariant-checker-1-shot-aggregator" aria-label="Permalink to &quot;\`@kiwa/release-invariants\` v0.1.0 (3 pure invariant checker + 1-shot aggregator)&quot;">​</a></h3><p>v1.29-3 で新規 npm package として land。 3 invariant checker + 1 aggregator の 4 export、 全て pure function (no I/O、 no side effects、 no kiwa 固有 dependency)。</p><ul><li><code>checkReleaseScriptFilter(releaseScript, publishable)</code> — 各 publishable package が build filter + publish filter <strong>両半分</strong> に含まれることを assert、 <code>partial: true</code> (片半分のみ) を検出</li><li><code>checkProvenanceFlagAbsence(releaseScript)</code> — v1.14 で <code>pnpm publish</code> から撤去した <code>--provenance</code> flag が creep back していないことを assert、 npm CLI 10+ OIDC federation が pnpm monorepo で不安定なため撤去した invariant</li><li><code>checkGateScriptPackageCoverage(mutationGateScript, publishable)</code> — <code>test:mutation</code> が全 publishable package を cover していることを assert、 v1.27 mutation sweep で baseline を確立した package を release-gate が漏れなく参照する invariant</li><li><code>buildReleaseInvariantsSummary({ releaseScript, mutationGateScript, publishable })</code> — 3 invariant を 1-shot で aggregate、 <code>ok: boolean</code> + 3 sub-result を return</li></ul><h3 id="_3-rule-ssot" tabindex="-1">3 rule SSOT <a class="header-anchor" href="#_3-rule-ssot" aria-label="Permalink to &quot;3 rule SSOT&quot;">​</a></h3><p><code>docs/concepts/release-invariants.md</code> は kiwa release-gate 全 invariant の 3 rule を単一 SSOT 化 (+ 2 補助 rule で合計 5 rule)。</p><ol><li><strong>release script filter 対称性</strong> — 全 publishable package が build filter + publish filter 両半分に含まれる。 半分のみは <code>partial: true</code> として detect、 4 回繰返された bug の直接原因。</li><li><strong>provenance flag 撤去</strong> — <code>pnpm publish</code> に <code>--provenance</code> が併記されない。 v1.14 で撤去済、 npm CLI 10+ OIDC federation が pnpm monorepo で不安定なため。</li><li><strong>gate script package 網羅</strong> — <code>test:mutation</code> が全 publishable package を filter に含む。 v1.27 mutation sweep で baseline を確立した package を release-gate が漏れなく参照する。</li><li><strong>1-shot summary via <code>buildReleaseInvariantsSummary</code></strong> — downstream release-smoke suite は通常 single boolean + 3 sub-result を 1 呼出で欲しい。 SSOT aggregator。</li><li><strong>7 milestone 連続 snippet validation streak</strong> — 各 tutorial code snippet は real npm package API に対して executable。 v1.23-v1.29 で 7 milestone 連続。</li></ol><h3 id="v1-29-1-release-smoke-test-axis-issue-986-pr-989" tabindex="-1">v1.29-1 release-smoke test axis (Issue #986, PR #989) <a class="header-anchor" href="#v1-29-1-release-smoke-test-axis-issue-986-pr-989" aria-label="Permalink to &quot;v1.29-1 release-smoke test axis (Issue #986, PR #989)&quot;">​</a></h3><p><code>tests/release-smoke/tests/release-script-filter.test.ts</code> (167 lines) を dynamic package discovery + 40 per-package <code>it.each</code> assert で新規 land。 <code>packages/*/package.json</code> を scan して <code>@kiwa/*</code> scope + <code>private: false</code> で filter、 各 publishable package が <strong>両半分</strong> に含まれることを assert。 milestone finisher <strong>前</strong> の fail-fast、 v1.30+ で 5 回目の反応的 fix が発生しない invariant。 同 PR で 6 未登録 package (agent / ai-llm / component / mcp / search / streaming) を filter に land、 v1.14 payment 漏れ 4 回目までの反応 pattern を止めて 5 回目予防 pattern に転換。</p><h3 id="v1-29-2-posttooluse-hook-issue-plan-checklist-ssot-issue-987" tabindex="-1">v1.29-2 PostToolUse hook + <code>/issue-plan</code> checklist SSOT (Issue #987) <a class="header-anchor" href="#v1-29-2-posttooluse-hook-issue-plan-checklist-ssot-issue-987" aria-label="Permalink to &quot;v1.29-2 PostToolUse hook + \`/issue-plan\` checklist SSOT (Issue #987)&quot;">​</a></h3><p><code>hooks/post-tool-use/release-script-filter-guard.sh</code> proactive prevention。 Write / Edit が <code>packages/*/package.json</code> を触った際に root package.json release script filter 存在を scan、 いずれか半分欠落を warn 出力 (hard-deny せず assist)。 <code>/issue-plan</code> skill body に「新 package 追加時の checklist」 SSOT を embed、 新 package 追加 Issue の body template に release script filter update を明示 (Issue body 段階で不変条件が明示される、 実装前の proactive 経路)。</p><h3 id="v1-29-3-release-invariants-docs-publish-issue-988" tabindex="-1">v1.29-3 release-invariants + docs + publish (Issue #988) <a class="header-anchor" href="#v1-29-3-release-invariants-docs-publish-issue-988" aria-label="Permalink to &quot;v1.29-3 release-invariants + docs + publish (Issue #988)&quot;">​</a></h3><p><code>@kiwa/release-invariants</code> v0.1.0 新規 package land + tutorial 55 (<code>release-script-filter-ssot.md</code> = systematic root cause pattern SSOT 化 walkthrough、 mock adapter + file adapter + 4 RED/GREEN behavior test の 15 分 walkthrough) + concept doc (<code>release-invariants.md</code> = 3 invariant SSOT + systematic root cause pattern + 4 回 rediscovery ledger + 7 milestone snippet validation streak) + migration guide (<code>v1.28-to-v1.29.md</code> = additive-only、 breaking change 0) + snippet validation (<code>packages/release-invariants/tests/docs-tutorial-v1.29.test.ts</code> = 8 test) + VitePress publish。 v1.23-1.28 pattern 転写で <strong>7 milestone 連続 pattern</strong> 化 (v1.23-v1.29) 達成。</p><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>3 sub-Issues resolved</strong> (#986 / #987 / #988) — kiwa milestone 史上最軽量 sprint</li><li><strong>3 PRs merged</strong> (v1.29-1 through v1.29-3)</li><li><strong>1 npm major addition</strong> (<code>@kiwa/release-invariants</code> v0.1.0) — kiwa runtime fixture 34 → <strong>35 packages</strong></li><li><strong>3 invariants</strong> (<code>checkReleaseScriptFilter</code> + <code>checkProvenanceFlagAbsence</code> + <code>checkGateScriptPackageCoverage</code>) + <strong>1 aggregator</strong> (<code>buildReleaseInvariantsSummary</code>)</li><li><strong>40 per-package assertion</strong> in <code>tests/release-smoke/tests/release-script-filter.test.ts</code></li><li><strong>8 snippet-validation tests</strong> in <code>packages/release-invariants/tests/docs-tutorial-v1.29.test.ts</code></li><li><strong>7 milestone 連続 snippet validation streak</strong> (v1.23 payment / v1.24 edge / v1.25 perf-harness / v1.26 orm / v1.27 quality-metrics / v1.28 realtime / v1.29 release-invariants)</li></ul><h2 id="why-これが「最終-layer」-なのか" tabindex="-1">Why これが「最終 layer」 なのか <a class="header-anchor" href="#why-これが「最終-layer」-なのか" aria-label="Permalink to &quot;Why これが「最終 layer」 なのか&quot;">​</a></h2><p>manual filter 更新から invariant checker + fail-fast test axis + PostToolUse hook + SSOT docs の <strong>4 layer 自動化</strong> に転換したのが v1.29 milestone の核心。 各 layer は独立して同じ bug を catch する。</p><ul><li><strong>Layer 1 — invariant checker</strong> (<code>@kiwa/release-invariants</code> v0.1)。 pure function、 downstream repo にも npm 経由 export。 3 pure function + 1 aggregator + 8 behavior test。</li><li><strong>Layer 2 — release-smoke test axis</strong> (<code>tests/release-smoke/tests/release-script-filter.test.ts</code>)。 dynamic package discovery + 40 per-package assert、 milestone finisher <strong>前</strong> の fail-fast。 「実 repo で今この瞬間」 の invariant を assert。</li><li><strong>Layer 3 — PostToolUse hook</strong> (<code>hooks/post-tool-use/release-script-filter-guard.sh</code>)。 Write / Edit が触った瞬間の warn、 test 実行前の proactive prevention。 実装中の contributor に catch。</li><li><strong>Layer 4 — SSOT docs</strong> (<code>docs/concepts/release-invariants.md</code> + tutorial 55 + migration guide)。 契約書 + walkthrough + migration path。 「なぜこの invariant なのか」 を 4 回 rediscovery ledger + 7 milestone streak で narrative 化。</li></ul><p>4 layer のいずれか 1 つでも通れば bug は catch される。 4 layer 全て bypass するには意図的な 4 か所同時修正が必要。 5 回目の release script filter miss は構造的遮断された。</p><h2 id="_18-→-19-milestone-streak" tabindex="-1">18 → 19 milestone streak <a class="header-anchor" href="#_18-→-19-milestone-streak" aria-label="Permalink to &quot;18 → 19 milestone streak&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (非決定性) → v1.13 (時間軸) → v1.14 (横軸拡張) → v1.15 (AI-LLM 深化) → v1.16 (component 縦軸) → v1.17 (Observability v2) → v1.18 (Blockchain 深化) → v1.19 (Framework 深化) → v1.20 (Streaming 深化) → v1.21 (Auth 深化) → v1.22 (Auth 深化 II) → v1.23 (Payment 深化) → v1.24 (Edge / Serverless 深化) → v1.25 (Perf-harness sweep) → v1.26 (Database 深化) → v1.27 (Mutation testing sweep) → v1.28 (Realtime 深化 II) → <strong>v1.29 (release script filter systematic root cause SSOT)</strong>。 v1.11 以降全 milestone sub-Issue 完遂維持。 v1.29 は最軽量 sprint (3 sub-Issue、 4 layer 自動化、 1 新 npm package)。</p><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><p><a href="https://github.com/cardene777/kiwa#roadmap" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa#roadmap</a></p><h2 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback&quot;">​</a></h2><ul><li>npm ... <code>pnpm add -D @kiwa/release-invariants@^0.1</code></li><li>GitHub Discussions ... <a href="https://github.com/cardene777/kiwa/discussions" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/discussions</a></li><li>Issue 起票 ... <a href="https://github.com/cardene777/kiwa/issues/new" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/issues/new</a></li></ul>`,34)])])}const g=a(r,[["render",o]]);export{h as __pageData,g as default};
